// Stands in for Max's `max-api` module so the bridge can run as a plain Node process in the tests.
const handlers = {};
module.exports = {
  post: (...args) => { if (process.env.RBOX_TEST_VERBOSE) console.log('[max post]', ...args); },
  outlet: () => {},
  addHandler: (name, fn) => { handlers[name] = fn; },
  handlers,
};
